#!/usr/bin/env python3
"""Overlay the native Home HQ port onto an isolated SAM13 MCU worktree."""
import argparse
import json
import re
import shutil
from pathlib import Path


def generate(target, home):
    from PIL import Image, ImageOps
    data = json.loads((home / "fixtures/demo.json").read_text())
    wire = json.dumps(data, separators=(",", ":"), ensure_ascii=False)
    (target / "homehq_demo.c").write_text(
        '#include "homehq.h"\n/* Shared authored fixture; generated by prepare.py. */\n'
        'const char homehq_demo_json[] = ' + json.dumps(wire) + ';\n')
    lines = ['#include "homehq.h"', '/* Native-size offline samples need no decode heap. */']
    for key in ("coast", "lake", "mountain"):
        image = Image.open(home / f"badge/homehq/assets/photo-{key}.png").convert("RGB")
        # Match downloaded photos: preserve the badge artwork's 4:3 aspect
        # ratio inside the wider native card, rather than stretching faces.
        scaled = ImageOps.contain(image, (128, 72), Image.Resampling.LANCZOS)
        image = Image.new("RGB", (128, 72), (242, 238, 230))
        image.paste(scaled, ((128-scaled.width)//2, (72-scaled.height)//2))
        pixels = []
        for red, green, blue in image.getdata():
            word = ((red >> 3) << 11) | ((green >> 2) << 5) | (blue >> 3)
            pixels.extend((word & 255, word >> 8))
        lines.append(f"static const uint8_t {key}_pixels[] = {{")
        lines.extend(" " + ",".join(map(str, pixels[i:i+48])) + "," for i in range(0, len(pixels), 48))
        lines.extend(("};", f"const lv_img_dsc_t homehq_photo_{key} = {{.header = {{.cf = LV_IMG_CF_TRUE_COLOR, .w = 128, .h = 72}}, .data_size = sizeof({key}_pixels), .data = {key}_pixels}};"))
    (target / "homehq_assets.c").write_text("\n".join(lines) + "\n")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--mcu", required=True, type=Path)
    args = parser.parse_args()
    port = Path(__file__).resolve().parents[1]
    target = args.mcu.resolve()
    main_c = target / "main/main.c"
    text = main_c.read_text()
    if '#include "boot_screen.h"' not in text and '#include "homehq.h"' not in text:
        raise SystemExit("Expected the documented SAM13 main.c; refuse an unknown firmware overlay")
    text = text.replace('#include "boot_screen.h"\n#include "camera_stream.h"', '#include "homehq.h"\n#include "homehq_console.h"')
    text = text.replace('lv_tick_inc(kLVGL_TickPeriod_us);', '// LVGL ticks are milliseconds; the hardware timer period is microseconds.\n    lv_tick_inc(kLVGL_TickPeriod_us / 1000);')
    text = text.replace('Camera_LockDisplay();\n        BootScreen_Maintain();', 'HQ_ConsolePoll();\n        HomeHQ_Maintain();')
    text = text.replace('        Camera_UnlockDisplay();\n', '')
    text = text.replace('Camera_IsLive() ? 10 : 30', '20')
    text = text.replace('BootScreen_Show(scr);', 'HomeHQ_Show(scr);')
    text = text.replace('Camera_Register();', 'HQ_ConsoleInit();\n    HQ_ServiceInit();')
    text = text.replace('#include "esp_timer.h"', '#include "esp_timer.h"\n#include "esp_heap_caps.h"') if '#include "esp_heap_caps.h"' not in text else text
    text = text.replace('static DMA_ATTR lv_color_t buffy[160*144];', '/* A static DMA section includes 46,080 zero bytes in the flash image.\n * Allocate once from internal DMA-capable RAM to fit the factory app region. */\nstatic lv_color_t *buffy;')
    text = text.replace('lv_color_t *buf1 = (lv_color_t*)&buffy;', 'buffy = heap_caps_calloc(160 * 144, sizeof(lv_color_t), MALLOC_CAP_DMA | MALLOC_CAP_INTERNAL);\n    configASSERT(buffy);\n    lv_color_t *buf1 = buffy;')
    text = text.replace('Camera/weather use their own canvas.', 'Home HQ owns the display.')
    text = text.replace('// Copy arriving camera pixels before rendering, avoiding a whole extra\n        // 30 ms loop of latency. Idle weather retains its original cadence.', '// Render on one core while the network worker performs blocking TLS.')
    text = text.replace('// Install the shared canvas mutex before the display task can use it.', '// All Home HQ widget/model changes run in this sole display task.')
    main_c.write_text(text)
    for source in (port / "src").rglob("*"):
        if source.is_file():
            destination = target / "main" / source.relative_to(port / "src")
            destination.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(source, destination)
    generate(target / "main", port.parent)
    cmake = (target / "main/CMakeLists.txt").read_text()
    sources = [f'"{p.relative_to(target / "main")}"' for p in (target / "main").rglob("homehq*.c")]
    sources += [f'"{p.relative_to(target / "main")}"' for p in (target / "main/vendor").rglob("*.c")] if (target / "main/vendor").exists() else []
    # Re-running after an implementation file arrives must update the same
    # source list, rather than silently retaining an earlier incomplete build.
    sources = ['"main.c"', '"gfx.c"', '"fpga_tx.c"', '"fpga_rx.c"', '"fpga_common.c"', '"pwrmgr.c"'] + sorted(set(sources))
    cmake = re.sub(r'SRCS\s+.*?\s+INCLUDE_DIRS', 'SRCS\n        ' + ' '.join(sources) + '\n    INCLUDE_DIRS', cmake, flags=re.S)
    cmake = cmake.replace('mbedtls esp_https_server', 'mbedtls esp_http_client json')
    cmake = cmake.replace('mbedtls esp_http_client json', 'mbedtls esp_http_client json tcp_transport')
    cmake = cmake.replace('tcp_transport tcp_transport', 'tcp_transport')
    if 'PNGLE_NO_GAMMA_CORRECTION' not in cmake:
        cmake += '\n# Streamed photos use their stored colour values; avoid a floating-point gamma table.\ntarget_compile_definitions(${COMPONENT_LIB} PRIVATE PNGLE_NO_GAMMA_CORRECTION)\n'
    (target / "main/CMakeLists.txt").write_text(cmake)
    config = (target / "sdkconfig.defaults").read_text()
    config = config.replace('CONFIG_APP_PROJECT_VER="0.13.4-sam13"', 'CONFIG_APP_PROJECT_VER="0.13.4-homehq1"')
    config = config.replace('CONFIG_CHROMATIC_FW_VER_STR="SAM13"', 'CONFIG_CHROMATIC_FW_VER_STR="HOMEHQ1"')
    config = config.replace('CONFIG_MBEDTLS_TLS_SERVER_ONLY=y', '# CONFIG_MBEDTLS_TLS_SERVER_ONLY is not set')
    config = config.replace('# CONFIG_MBEDTLS_TLS_SERVER_AND_CLIENT is not set', '# CONFIG_MBEDTLS_TLS_SERVER_AND_CLIENT is not set\nCONFIG_MBEDTLS_TLS_CLIENT_ONLY=y')
    config = config.replace('# CONFIG_MBEDTLS_CERTIFICATE_BUNDLE is not set', 'CONFIG_MBEDTLS_CERTIFICATE_BUNDLE=y\nCONFIG_MBEDTLS_CERTIFICATE_BUNDLE_DEFAULT_CMN=y')
    config = config.replace('# CONFIG_MBEDTLS_KEY_EXCHANGE_ECDHE_RSA is not set', 'CONFIG_MBEDTLS_KEY_EXCHANGE_ECDHE_RSA=y')
    config += '\nCONFIG_LV_FONT_MONTSERRAT_10=y\nCONFIG_LV_FONT_MONTSERRAT_12=y\nCONFIG_LV_FONT_MONTSERRAT_20=y\n'
    # ESP32 has standard nano printf/scanf in ROM. Home HQ uses 32-bit integers
    # and standard floating formats, avoiding the full formatter's flash cost.
    config += '\nCONFIG_NEWLIB_NANO_FORMAT=y\n'
    # The generic theme references every enabled widget, including unused
    # charts/meters/tab views. Home HQ styles its own objects; linking those
    # widgets caused a measured 153,696-byte factory-partition overflow.
    config += '\n# CONFIG_LV_USE_THEME_DEFAULT is not set\n# CONFIG_LV_USE_THEME_BASIC is not set\n# CONFIG_LV_USE_THEME_MONO is not set\nCONFIG_LV_USE_FLEX=y\nCONFIG_LV_USE_GRID=y\n'
    # Kconfig defaults are sets of values, not an append-only deployment log.
    # Remove repeated identical setting lines left by incremental preparations.
    seen = set()
    unique = []
    for line in config.splitlines():
        if re.match(r'(?:# )?CONFIG_[A-Z0-9_]+(?:=| is not set)', line):
            if line in seen:
                continue
            seen.add(line)
        unique.append(line)
    (target / "sdkconfig.defaults").write_text("\n".join(unique) + "\n")
    # defaults apply only to unset symbols. Update the existing isolated build
    # config too, so an incremental build cannot retain server TLS/themes.
    existing = target / "sdkconfig"
    if existing.exists():
        current = existing.read_text()
        for symbol in ('MBEDTLS_TLS_SERVER_AND_CLIENT', 'MBEDTLS_TLS_SERVER_ONLY', 'LV_USE_THEME_DEFAULT', 'LV_USE_THEME_BASIC', 'LV_USE_THEME_MONO'):
            current = re.sub(rf'CONFIG_{symbol}=y', f'# CONFIG_{symbol} is not set', current)
        current = current.replace('# CONFIG_MBEDTLS_TLS_CLIENT_ONLY is not set', 'CONFIG_MBEDTLS_TLS_CLIENT_ONLY=y')
        for symbol in ('LV_USE_FLEX', 'LV_USE_GRID'):
            current = current.replace(f'# CONFIG_{symbol} is not set', f'CONFIG_{symbol}=y')
        current = current.replace('# CONFIG_NEWLIB_NANO_FORMAT is not set', 'CONFIG_NEWLIB_NANO_FORMAT=y')
        existing.write_text(current)
    print(f"Prepared isolated Home HQ MCU source: {target}")


if __name__ == "__main__":
    main()
